window.CONECTORES=[["Preposiciones","Relacionan una palabra con otra. Úsalas para decir lugar, tiempo, causa o destino.",[["a","Dirección, hora o persona que recibe una acción.","Voy a la iglesia a las nueve."],["con","Compañía o instrumento.","Hablo con mi abogado."],["en","Lugar o momento.","El contrato está en la mesa."],["de","Origen, posesión o tema.","Hablamos de la fe."],["para","Meta, destino o para quién.","Este poder es para mi madre."],["por","Causa, medio, a cambio o por dónde. Para = meta; por = causa o camino.","Te lo envío por correo por tu seguridad."],["sin","Algo que falta.","No firmes sin leer."],["sobre","Tema o posición encima.","La lección es sobre la oración."],["entre","En medio de dos o más.","Es un acuerdo entre dos personas."],["hasta","Límite de tiempo o lugar.","Trabajo hasta las cinco."],["desde","Punto de inicio.","Vivo aquí desde enero."],["hacia","Dirección aproximada.","Camino hacia el templo."],["contra","Oposición o contacto.","Votaron contra la propuesta."]]],["Relativos","Unen frases sobre personas o cosas para no repetir sus nombres. Úsalos para añadir información.",[["que","Para personas o cosas.","El libro que leo es interesante."],["quien","Solo una persona; después de una preposición o entre comas.","La abogada con quien hablé me ayudó."],["quienes","Solo dos o más personas; después de preposición o entre comas.","Mis primos, quienes llegaron ayer, nos visitan."],["el que / la que / los que / las que","Señalan una persona o cosa; concuerdan en género y número.","La que firma es mi madre."],["lo que","Una idea o algo sin nombre concreto.","No entiendo lo que dice el contrato."],["cuyo / cuya / cuyos / cuyas","Posesión: concuerda con la cosa poseída, no con su dueño.","El cliente cuya casa vendimos está contento."],["donde","Un lugar.","Esta es la capilla donde me bauticé."]]],["Conjunciones","Unen palabras o ideas. Úsalas para sumar, elegir, explicar o mostrar un contraste.",[["y / e","Suma ideas. Usa e antes del sonido i (i-/hi-); no ante el sonido de hielo.","Estudiamos español e historia."],["o / u","Da opciones. Usa u antes del sonido o (o-/ho-).","¿Mañana u hoy?"],["pero","Contraste entre dos ideas.","Es difícil, pero puedo hacerlo."],["sino","Corrige una idea después de un no.","No es un testamento, sino un poder."],["porque","Explica una causa.","Oro porque necesito ayuda."],["aunque","Algo no impide la otra acción.","Voy aunque llueva."],["entonces","Resultado o siguiente momento.","Terminó la reunión; entonces salimos."],["así que","Resultado de lo que acabas de decir.","Ya leí el contrato, así que puedo firmar."],["mientras","Dos acciones al mismo tiempo.","Escucho mientras camino."],["cuando","El momento de una acción.","Te llamo cuando llegue."],["si","Una condición; sin tilde.","Si tienes dudas, pregunta."]]]];
